import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname, extname, join } from 'node:path';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec('CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id ASC');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');

const mime = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(typeof body === 'string' ? body : JSON.stringify(body));
}
async function bodyJson(req) {
  let text = '';
  for await (const chunk of req) text += chunk;
  return JSON.parse(text || '{}');
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  try {
    if (url.pathname === '/health' && req.method === 'GET') return send(res, 200, { status: 'ok' });
    if (url.pathname === '/api/projects' && req.method === 'GET') return send(res, 200, listProjects.all());
    if (url.pathname === '/api/projects' && req.method === 'POST') {
      const input = await bodyJson(req);
      const name = typeof input.name === 'string' ? input.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return send(res, 201, getProject.get(Number(result.lastInsertRowid)));
    }
    const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
    if (projectMatch && req.method === 'GET') {
      const project = getProject.get(Number(projectMatch[1]));
      return project ? send(res, 200, project) : send(res, 404, { error: 'Project not found' });
    }
    if (req.method === 'GET') {
      const file = url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname) ? 'index.html' : url.pathname.slice(1);
      if (file.includes('..')) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
      try {
        const content = await readFile(join(root, 'public', file));
        return send(res, 200, content, mime[extname(file)] || 'application/octet-stream');
      } catch { return send(res, 404, 'Not found', 'text/plain; charset=utf-8'); }
    }
    send(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error instanceof SyntaxError) return send(res, 400, { error: 'Invalid JSON' });
    console.error(error);
    send(res, 500, { error: 'Internal server error' });

